import { $, esc, showToast } from "./dom.js";
import { appState, normalPlaceholders, stablePlaceholders, products, productSources, rules, newRule, operatorOptions } from "./state.js";
import { renderAnnotations } from "./annotations.js";
import { openConfirmationDialog } from "./confirmation-dialog.js";

const product = () => products.find(item => item.id === appState.selectedProductId) || products[0];
const sources = () => productSources[appState.selectedProductId] || { thingModels: [], countdowns: [], consumables: [] };
const isSummary = () => appState.rule.ruleType === "DAILY_SUMMARY";
const steps = () => isSummary() ? [[1, "消息内容", "名称、文案和预览"], [2, "汇总范围", "关联项和预计日期"], [3, "投递设置", "每日时间和目标"]] : [[1, "消息内容", "名称、文案和跳转"], [2, "触发条件", "来源、条件与提醒时间"], [3, "投递设置", "目标与发送方式"]];
const selectedModel = () => sources().thingModels.find(item => item.id === appState.rule.thingModelId) || sources().thingModels[0];
const selectedConsumable = () => sources().consumables.find(item => item.id === appState.rule.consumableId) || sources().consumables[0];
const sourceLabel = item => item.sourceType === "COUNTDOWN" ? "云计时器" : "云端定时耗材";
let pickerState = { query: "", kind: "all" };

function stepNav() { return `<nav class="step-nav" id="ruleStepNav" data-anchor="step-nav"><div class="step-progress"><span>${isSummary() ? "汇总推送配置" : "普通推送配置"}</span><strong>步骤 ${appState.ruleStep} / 3</strong></div><ol class="step-list">${steps().map(([number, title, subtitle], index) => `<li class="step-slot"><button class="step-item ${number === appState.ruleStep ? "active" : ""} ${number < appState.ruleStep ? "is-complete" : ""}" data-step="${number}"><span class="step-index">${number < appState.ruleStep ? "✓" : number}</span><span class="step-copy"><strong>${title}</strong><small>${subtitle}</small></span></button>${index < 2 ? `<span class="step-connector ${number < appState.ruleStep ? "is-complete" : ""}"></span>` : ""}</li>`).join("")}</ol></nav>`; }
function placeholderPanel(tokens, note) { return `<div class="placeholder-area" data-anchor="placeholder-panel"><div><strong>插入内容</strong><span>${note}</span></div><div class="placeholder-panel">${tokens.map(token => `<button type="button" class="placeholder" data-placeholder="${esc(token)}">${esc(token)}</button>`).join("")}</div></div>`; }
function preview(title, body, items = [], itemsIntro = "") { return `<section class="preview-section" data-anchor="message-previews"><div class="section-title"><h3>发送效果</h3><p>${items.length ? "关联项仅显示在 App 消息详情" : "消息中心和系统 notification 预览"}</p></div><div class="message-preview-grid"><article class="preview-pane"><span class="preview-eyebrow">系统 notification</span><div class="notification-preview"><strong>${esc(title || "Message title")}</strong><p>${esc(body || "Message body")}</p><small>现在 · ${esc(product().model)}</small></div><div class="preview-foot">${items.length ? "不展示关联项" : "可选投递"}</div></article><article class="preview-pane"><span class="preview-eyebrow">App 消息列表</span><div class="inbox-row"><span class="inbox-icon">M</span><div><strong>${esc(title || "Message title")}</strong><p>${esc(body || "Message body")}</p><small>今天</small></div><i></i></div><div class="preview-foot">一条消息记录</div></article><article class="preview-pane"><span class="preview-eyebrow">App 消息详情</span><div class="detail-preview"><strong>${esc(title || "Message title")}</strong><p>${esc(body || "Message body")}</p>${items.length ? `${itemsIntro.trim() ? `<p class="summary-items-intro">${esc(itemsIntro)}</p>` : ""}<ul class="summary-items-list">${items.map(item => `<li>${esc(item.label || "关联项文本")}</li>`).join("")}</ul>` : ""}</div><div class="preview-foot">${items.length ? "按发送时的预测快照展示" : "按规则内容展示"}</div></article></div></section>`; }
function messageStep() {
  const rule = appState.rule;
  return `<div id="ruleStepContent"><div class="form-section"><div class="section-title"><h3>${isSummary() ? "汇总信息" : "规则信息"}</h3><p>当前产品：${esc(product().name)}</p></div><label class="form-row"><span class="form-label"><i class="required">*</i>${isSummary() ? "汇总名称" : "规则名称"}</span><input class="el-input" data-rule-input="name" value="${esc(rule.name)}" placeholder="${isSummary() ? "例如：清洗提醒" : "例如：储奶量过高提醒"}"><p class="form-help">仅在管理端识别，不展示给 App 用户。</p></label></div><div class="form-section"><div class="section-title"><h3>English 消息内容</h3><p>${isSummary() ? "Title 和 Body 由这条汇总推送直接拥有" : "默认语言为 English"}</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>Title</span><input class="el-input" maxlength="100" data-content="title" value="${esc(rule.title)}"></label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body</span><textarea class="el-textarea" maxlength="200" data-content="body">${esc(rule.body)}</textarea></label>${!isSummary() ? `<label class="form-row full"><span class="form-label">点击后打开</span><select class="el-select" data-rule-input="presetLinkId">${product().presetLinks.map(link => `<option value="${link.id}" ${link.id === rule.presetLinkId ? "selected" : ""}>${esc(link.label)}${link.id === "message-center" ? "（默认）" : ""}</option>`).join("")}</select></label>` : `<div class="readonly-field">点击位置固定进入本条汇总消息详情。</div>`}</div>${placeholderPanel(isSummary() ? stablePlaceholders : normalPlaceholders, isSummary() ? "仅支持设备和账号信息" : "先点 Title 或 Body，再选择")}</div>${preview(rule.title, rule.body, isSummary() ? rule.items : [], rule.itemsIntro || "")}</div>`;
}
function modelMeta(model) { return model ? `${model.kind === "event" ? "事件" : model.dataType}${model.unit ? ` · ${model.unit}` : ""} · ${model.id}` : ""; }
function matchingModels() { const keyword = pickerState.query.trim().toLowerCase(); return sources().thingModels.filter(item => (pickerState.kind === "all" || item.kind === pickerState.kind) && (!keyword || `${item.name} ${item.id}`.toLowerCase().includes(keyword))); }
function pickerShell() { const rows = matchingModels(), current = selectedModel(); return `<div class="property-picker-host is-open" id="propertyPicker"><div class="property-picker-mask" data-picker-close></div><section class="property-picker"><header class="property-picker-header"><div><h3>选择物模型</h3><p>属性按数据类型配置条件；事件上报即触发。</p></div><button class="icon-btn" data-picker-close>×</button></header><div class="property-picker-toolbar"><div class="property-search"><span>⌕</span><input class="el-input" data-model-query value="${esc(pickerState.query)}" placeholder="搜索名称或标识符"><kbd>Esc</kbd></div><div class="segmented"><button class="${pickerState.kind === "all" ? "active" : ""}" data-model-kind="all">全部</button><button class="${pickerState.kind === "property" ? "active" : ""}" data-model-kind="property">属性</button><button class="${pickerState.kind === "event" ? "active" : ""}" data-model-kind="event">事件</button></div></div><div class="property-picker-body"><section class="property-results"><div class="property-results-head"><span>${pickerState.query ? `“${esc(pickerState.query)}” 的结果` : "可选物模型"}</span><small>${rows.length} 个</small></div><div class="property-option-list">${rows.length ? rows.map(item => `<button class="property-option ${item.id === current?.id ? "selected" : ""}" data-select-model="${item.id}"><span class="property-type-icon">${item.kind === "event" ? "E" : item.dataType === "enum" ? "≡" : item.dataType === "string" ? "T" : "#"}</span><span class="property-option-copy"><strong>${esc(item.name)}</strong><small>${esc(modelMeta(item))}</small></span><span class="property-option-side"><b>${item.id === current?.id ? "已选" : "选择"}</b></span></button>`).join("") : `<div class="property-empty"><strong>没有匹配结果</strong><span>可换个名称搜索。</span></div>`}</div></section></div><footer class="property-picker-footer"><span>来源：当前产品物模型配置</span><button class="el-btn" data-picker-close>取消</button></footer></section></div>`; }
function closePicker() { $("#propertyPicker")?.remove(); }
function selectModel(model) { Object.assign(appState.rule, { thingModelId: model.id, operator: operatorOptions[model.dataType][0], conditionValues: [], conditionValue: model.kind === "event" ? "true" : model.dataType === "bool" ? "true" : model.dataType === "enum" ? model.options[0]?.value || "" : model.example || "" }); }
function wirePicker() { const host = $("#propertyPicker"); host.querySelectorAll("[data-picker-close]").forEach(button => button.onclick = closePicker); host.querySelector("[data-model-query]").oninput = event => { pickerState.query = event.target.value; host.outerHTML = pickerShell(); wirePicker(); }; host.querySelectorAll("[data-model-kind]").forEach(button => button.onclick = () => { pickerState.kind = button.dataset.modelKind; host.outerHTML = pickerShell(); wirePicker(); }); host.querySelectorAll("[data-select-model]").forEach(button => button.onclick = () => { const model = sources().thingModels.find(item => item.id === button.dataset.selectModel); if (model) { selectModel(model); closePicker(); rerender(); showToast(`已选择：${model.name}`); } }); }
function openPicker() { pickerState = { query: "", kind: "all" }; $("#overlayRoot").insertAdjacentHTML("beforeend", pickerShell()); wirePicker(); }
function conditionValueControl(model) { const rule = appState.rule; if (model.kind === "event") return `<div class="readonly-field">true（设备上报事件时触发）</div>`; if (model.dataType === "bool") return `<select class="el-select" data-rule-input="conditionValue"><option value="true" ${rule.conditionValue === "true" ? "selected" : ""}>true</option><option value="false" ${rule.conditionValue === "false" ? "selected" : ""}>false</option></select>`; if (model.dataType === "enum") { const multi = ["包含", "不包含"].includes(rule.operator); return multi ? `<div class="enum-values">${model.options.map(option => `<label><input type="checkbox" data-enum-value="${option.value}" ${(rule.conditionValues || []).includes(option.value) ? "checked" : ""}>${esc(option.label)} <small>${esc(option.value)}</small></label>`).join("")}</div><p class="form-help">${rule.operator === "包含" ? "上报值属于所选集合时触发。" : "上报值不属于所选集合时触发；不能选择全部值。"}</p>` : `<select class="el-select" data-rule-input="conditionValue">${model.options.map(option => `<option value="${option.value}" ${option.value === rule.conditionValue ? "selected" : ""}>${esc(option.label)} (${esc(option.value)})</option>`).join("")}</select>`; } if (["int32", "int64", "float", "double"].includes(model.dataType)) return `<div class="threshold-control"><input class="el-input" type="number" ${model.dataType.startsWith("int") ? "step=\"1\"" : `step="${model.step}"`} min="${model.min}" max="${model.max}" data-rule-input="conditionValue" value="${esc(rule.conditionValue)}"><span>${esc(model.unit || "")}</span></div><p class="form-help">范围 ${model.min}-${model.max}，步进 ${model.step}。</p>`; return `<input class="el-input" maxlength="${model.maxLength}" data-rule-input="conditionValue" value="${esc(rule.conditionValue)}" placeholder="${["包含", "不包含"].includes(rule.operator) ? "输入一个关键词" : "输入文本"}"><p class="form-help">区分大小写；按原文匹配，不支持正则、通配符或多个关键词。</p>`; }
function timeWindow() { const rule = appState.rule, custom = rule.timeMode === "custom", cross = rule.timeStart > rule.timeEnd; return `<div class="form-section" data-anchor="trigger-time"><div class="section-title"><h3>提醒时间</h3><p>触发条件和这里的设置都满足时才提醒</p></div><div class="radio-row time-mode-row"><label class="choice-card ${!custom ? "selected" : ""}"><input type="radio" name="time-mode" value="all-day" ${!custom ? "checked" : ""}><span class="choice-copy"><strong>全天</strong><small>不限制提醒发生的时间</small></span></label><label class="choice-card ${custom ? "selected" : ""}"><input type="radio" name="time-mode" value="custom" ${custom ? "checked" : ""}><span class="choice-copy"><strong>指定时段</strong><small>只在设定的时间内提醒</small></span></label></div>${custom ? `<div class="time-range"><input class="el-input" type="time" data-rule-input="timeStart" value="${esc(rule.timeStart)}"><span>至</span><input class="el-input" type="time" data-rule-input="timeEnd" value="${esc(rule.timeEnd)}"><span class="el-tag el-tag--${cross ? "warning" : "info"} is-plain">${cross ? "跨到次日" : "当天"}</span></div>` : `<div class="all-day-summary"><strong>全天</strong><span>每个自然日内均可触发提醒。</span></div>`}</div>`; }
function normalTriggerStep() { const rule = appState.rule, model = selectedModel(), consumable = selectedConsumable(); let detail = ""; if (rule.triggerType === "device") detail = `<div class="form-grid"><div class="form-row full" data-anchor="property-selector"><span class="form-label"><i class="required">*</i>物模型</span><button class="property-select-trigger" data-open-picker><span class="property-select-main"><strong>${esc(model?.name || "请选择")}</strong><small>${esc(modelMeta(model))}</small></span><span class="property-select-action">选择 / 更换 ›</span></button></div><label class="form-row"><span class="form-label"><i class="required">*</i>运算符</span><select class="el-select" data-rule-input="operator" ${model?.kind === "event" ? "disabled" : ""}>${operatorOptions[model?.dataType || "string"].map(operator => `<option ${operator === rule.operator ? "selected" : ""}>${operator}</option>`).join("")}</select></label><div class="form-row"><span class="form-label"><i class="required">*</i>条件值</span>${conditionValueControl(model)}</div></div>`; if (rule.triggerType === "cloud") { const timer = sources().countdowns.find(item => item.id === rule.cloudCountdownId) || sources().countdowns[0]; detail = `<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>云计时器</span><select class="el-select" data-rule-input="cloudCountdownId">${sources().countdowns.map(item => `<option value="${item.id}" ${item.id === rule.cloudCountdownId ? "selected" : ""}>${esc(item.name)} · 每 ${item.duration} ${item.unit}</option>`).join("")}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>剩余时长</span><div class="threshold-control"><input class="el-input" type="number" min="0" max="${timer.duration}" data-rule-input="cloudThreshold" value="${esc(rule.cloudThreshold)}"><span>${esc(timer.unit)}</span></div><p class="form-help">剩余时长小于或等于这个值时触发。</p></label></div>`; } if (rule.triggerType === "consumable") detail = `<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>耗材项</span><select class="el-select" data-rule-input="consumableId">${sources().consumables.map(item => `<option value="${item.id}" ${item.id === rule.consumableId ? "selected" : ""}>${esc(item.name)} · ${esc(item.typeLabel)}</option>`).join("")}</select><p class="form-help">当前类型：${esc(consumable?.typeLabel || "-")}。</p></label><label class="form-row"><span class="form-label"><i class="required">*</i>触发项</span><select class="el-select" data-rule-input="consumableEvent"><option value="low" ${rule.consumableEvent === "low" ? "selected" : ""}>不足</option><option value="empty" ${rule.consumableEvent === "empty" ? "selected" : ""}>耗尽</option></select></label></div>`; return `<div id="ruleStepContent"><div class="form-section" data-anchor="trigger-source"><div class="section-title"><h3>触发源</h3><p>决定什么时候产生提醒</p></div><div class="radio-row">${[["device", "设备触发", "物模型属性或事件"], ["cloud", "云端触发", "云计时器剩余时长"], ["consumable", "耗材触发", "不足或耗尽"]].map(([value, label, help]) => `<label class="choice-card ${rule.triggerType === value ? "selected" : ""}"><input type="radio" name="trigger" value="${value}" ${rule.triggerType === value ? "checked" : ""}><span class="choice-copy"><strong>${label}</strong><small>${help}</small></span></label>`).join("")}</div><div class="trigger-detail">${detail}</div></div>${timeWindow()}<div class="form-section" data-anchor="recipient-resolution"><div class="section-title"><h3>接收者</h3><p>无需单独配置</p></div><div class="readonly-field">触发设备的全部绑定用户；无绑定用户时不发送。</div></div></div>`; }
function itemName(item) { const source = item.sourceType === "COUNTDOWN" ? sources().countdowns.find(entry => entry.id === item.sourceId) : sources().consumables.find(entry => entry.id === item.sourceId); return source?.name || "已删除的关联对象"; }
function duplicateNotice(item) { return rules.filter(rule => rule.ruleType === "DAILY_SUMMARY" && rule.id !== appState.rule.id).filter(rule => rule.items?.some(entry => entry.sourceType === item.sourceType && entry.sourceId === item.sourceId && String(entry.condition) === String(item.condition))).map(rule => rule.name); }
function summaryRangeStep() { const items = [...appState.rule.items].sort((a,b) => a.displayOrder - b.displayOrder); return `<div id="ruleStepContent"><div class="form-section" data-anchor="summary-range"><div class="section-title"><h3>关联项</h3><p>选择当日可预测的云计时器或云端定时耗材</p></div><div class="help-alert"><strong>汇总方式：</strong>每天在发送时间预测同一设备当天会命中的关联项。0 项不发送；1 项或多项均只发送一条消息。</div><label class="form-row summary-intro-field"><span class="form-label">关联项引导文案（可选）</span><textarea class="el-textarea" maxlength="100" data-rule-input="itemsIntro" placeholder="例如：Items to take care of:">${esc(appState.rule.itemsIntro || "")}</textarea><p class="form-help">显示在 App 消息详情的 Body 和关联项之间；不填写时，不显示额外固定文案。</p></label><div class="summary-item-list">${items.length ? items.map((item, index) => `<article class="summary-item"><div class="summary-item-order">${index + 1}</div><div class="summary-item-copy"><strong>${esc(itemName(item))}</strong><span>${sourceLabel(item)} · ${item.sourceType === "COUNTDOWN" ? `剩余时长 ≤ ${esc(item.condition)} ${(sources().countdowns.find(entry => entry.id === item.sourceId)?.unit || "")}` : (item.condition === "low" ? "不足" : "耗尽")}</span><small>${esc(item.label)}</small>${duplicateNotice(item).length ? `<em>与“${esc(duplicateNotice(item).join("、"))}”关联相同对象；允许保存，但当天可能重复提醒。</em>` : ""}</div><div class="summary-item-actions"><button class="op-link" data-edit-item="${esc(item.itemId)}">编辑</button><button class="op-link" data-move-item="${esc(item.itemId)}" data-direction="-1" ${index === 0 ? "disabled" : ""}>上移</button><button class="op-link" data-move-item="${esc(item.itemId)}" data-direction="1" ${index === items.length - 1 ? "disabled" : ""}>下移</button><button class="op-link danger" data-delete-item="${esc(item.itemId)}">删除</button></div></article>`).join("") : `<div class="empty-inline">还没有关联项。添加至少一项后才能发布汇总推送。</div>`}</div><button class="el-btn" data-add-item>+ 新增关联项</button></div><div class="form-section"><div class="section-title"><h3>接收者</h3><p>按设备生成独立消息</p></div><div class="readonly-field">每位设备绑定用户分别生成一条消息中心记录。</div></div></div>`; }
function deliveryStep() { const rule = appState.rule; return `<div id="ruleStepContent"><div class="form-section" data-anchor="delivery-target"><div class="section-title"><h3>投递目标</h3><p>App 消息中心始终投递</p></div><div class="delivery-targets"><label class="choice-card selected locked"><input type="checkbox" checked disabled><span class="choice-copy"><strong>App 消息中心</strong><small>必选，不能关闭</small></span></label><label class="choice-card ${rule.systemNotificationEnabled ? "selected" : ""}"><input type="checkbox" name="system-notification" ${rule.systemNotificationEnabled ? "checked" : ""}><span class="choice-copy"><strong>系统 notification</strong><small>在手机系统通知栏额外提醒</small></span></label></div></div>${isSummary() ? `<div class="form-section" data-anchor="summary-delivery"><div class="section-title"><h3>每日发送</h3><p>使用产品时区，每天最多一次</p></div><label class="form-row interval-field"><span class="form-label"><i class="required">*</i>发送时间</span><input class="el-input" type="time" data-rule-input="sendTime" value="${esc(rule.sendTime || "09:00")}"><p class="form-help">默认 09:00。此时间预测当天关联项；发送后不会更新、补发或重新计算。</p></label><div class="summary-card"><h4>固定投递方式</h4><p>点击消息进入本条汇总消息详情。系统 notification 仅展示 Title / Body，不展示关联项。</p><div class="summary-key">同一用户 + 同一设备 + 同一汇总推送 + 同一自然日，最多一条消息。</div></div></div>` : `<div class="form-section" data-anchor="delivery-mode"><div class="section-title"><h3>发送方式</h3><p>仅影响当前普通推送</p></div><div class="radio-row"><label class="choice-card ${rule.reminderMode === "each" ? "selected" : ""}"><input type="radio" name="mode" value="each" ${rule.reminderMode === "each" ? "checked" : ""}><span class="choice-copy"><strong>逐条发送</strong><small>每次满足条件都发送</small></span></label><label class="choice-card ${rule.reminderMode === "discard" ? "selected" : ""}"><input type="radio" name="mode" value="discard" ${rule.reminderMode === "discard" ? "checked" : ""}><span class="choice-copy"><strong>仅发送首条</strong><small>一段时间内只发送第一次</small></span></label></div>${rule.reminderMode === "discard" ? `<label class="form-row interval-field" data-anchor="min-interval"><span class="form-label"><i class="required">*</i>最小发送间隔</span><div class="threshold-control"><input class="el-input" type="number" min="5" max="10080" data-rule-input="minIntervalMinutes" value="${esc(rule.minIntervalMinutes)}"><span>分钟</span></div></label>` : ""}</div>`}<div class="form-section" data-anchor="validation"><div class="section-title"><h3>发布检查</h3><p>保存草稿不阻塞，发布时校验必填项</p></div><div class="help-alert ${validate().length ? "warning" : "success"}">${validate().length ? validate().map(esc).join("；") : "当前配置可以发布。"}</div></div></div>`; }
function itemDialog(existing = null) { const draft = existing ? { ...existing } : { itemId: `item-${Date.now()}`, sourceType: "COUNTDOWN", sourceId: sources().countdowns[0]?.id || "", condition: "0", label: "", displayOrder: appState.rule.items.length + 1 }; const render = () => { const sourceOptions = draft.sourceType === "COUNTDOWN" ? sources().countdowns : sources().consumables.filter(item => item.type === "cloud-timed"); const source = sourceOptions.find(item => item.id === draft.sourceId) || sourceOptions[0]; if (source) draft.sourceId = source.id; return `<div class="modal-host" id="summaryItemDialog"><section class="modal summary-item-dialog" role="dialog" aria-modal="true"><header class="modal-header"><div><h3>${existing ? "编辑关联项" : "新增关联项"}</h3><p>关联项文本是静态多语言内容，不支持占位符。</p></div><button class="icon-btn" data-item-close>×</button></header><div class="modal-body"><label class="form-row"><span class="form-label"><i class="required">*</i>对象类型</span><select class="el-select" data-item-field="sourceType"><option value="COUNTDOWN" ${draft.sourceType === "COUNTDOWN" ? "selected" : ""}>云计时器</option><option value="CLOUD_TIMED_CONSUMABLE" ${draft.sourceType === "CLOUD_TIMED_CONSUMABLE" ? "selected" : ""}>云端定时耗材</option></select></label><label class="form-row"><span class="form-label"><i class="required">*</i>${draft.sourceType === "COUNTDOWN" ? "云计时器" : "耗材项"}</span><select class="el-select" data-item-field="sourceId">${sourceOptions.map(item => `<option value="${item.id}" ${item.id === draft.sourceId ? "selected" : ""}>${esc(item.name)}${item.unit ? ` · ${item.unit}` : ""}</option>`).join("")}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>${draft.sourceType === "COUNTDOWN" ? "剩余时长" : "触发项"}</span>${draft.sourceType === "COUNTDOWN" ? `<div class="threshold-control"><input class="el-input" type="number" min="0" max="${source?.duration || 999}" data-item-field="condition" value="${esc(draft.condition)}"><span>${esc(source?.unit || "")}</span></div><p class="form-help">剩余时长小于或等于这个值时命中。</p>` : `<select class="el-select" data-item-field="condition"><option value="low" ${draft.condition === "low" ? "selected" : ""}>不足</option><option value="empty" ${draft.condition === "empty" ? "selected" : ""}>耗尽</option></select>`}</label><label class="form-row"><span class="form-label"><i class="required">*</i>English 关联项文本</span><input class="el-input" maxlength="100" data-item-field="label" value="${esc(draft.label)}" placeholder="例如：Replace breast shields"><p class="form-help">显示在 App 消息详情的关联项列表中，不进入系统 notification 正文。</p></label></div><footer class="modal-footer"><button class="el-btn" data-item-close>取消</button><button class="el-btn el-btn--primary" data-item-save>保存关联项</button></footer></section></div>`; }; $("#overlayRoot").insertAdjacentHTML("beforeend", render()); const wire = () => { const host = $("#summaryItemDialog"); host.querySelectorAll("[data-item-close]").forEach(button => button.onclick = () => host.remove()); host.addEventListener("click", event => { if (event.target === host) host.remove(); }); host.querySelectorAll("[data-item-field]").forEach(input => input.oninput = () => { draft[input.dataset.itemField] = input.value; if (input.dataset.itemField === "sourceType") { draft.sourceId = ""; draft.condition = input.value === "COUNTDOWN" ? "0" : "low"; host.outerHTML = render(); wire(); } }); host.querySelector("[data-item-save]").onclick = () => { const duplicate = appState.rule.items.some(item => item.itemId !== draft.itemId && item.sourceType === draft.sourceType && item.sourceId === draft.sourceId && String(item.condition) === String(draft.condition)); if (!draft.label.trim()) return showToast("请填写 English 关联项文本", "error"); if (duplicate) return showToast("同一汇总推送不能重复关联相同对象和条件", "error"); const index = appState.rule.items.findIndex(item => item.itemId === draft.itemId); if (index >= 0) appState.rule.items[index] = draft; else appState.rule.items.push(draft); appState.rule.items.forEach((item, index) => item.displayOrder = index + 1); host.remove(); rerender(); }; }; wire(); }
function validate() { const rule = appState.rule, issues = []; if (!rule.name.trim()) issues.push(`${isSummary() ? "汇总名称" : "规则名称"}未填写`); if (!rule.title.trim() || !rule.body.trim()) issues.push("English Title 和 Body 必填"); if (isSummary()) { if (!rule.items.length) issues.push("至少添加一个关联项"); if (!/^\d{2}:\d{2}$/.test(rule.sendTime || "")) issues.push("请设置每日发送时间"); rule.items.forEach(item => { if (!item.label?.trim()) issues.push("关联项 English 文本必填"); }); } else { const model = selectedModel(); if (model?.dataType === "enum" && ["包含", "不包含"].includes(rule.operator) && !rule.conditionValues?.length) issues.push("请至少选择一个枚举值"); if (model?.dataType === "enum" && rule.operator === "不包含" && rule.conditionValues?.length === model.options.length) issues.push("不能排除全部枚举值"); if (model?.dataType === "string" && !String(rule.conditionValue || "").trim()) issues.push("关键词不能为空"); if (rule.reminderMode === "discard" && (+rule.minIntervalMinutes < 5 || +rule.minIntervalMinutes > 10080)) issues.push("最小发送间隔需为 5-10080 分钟"); } return [...new Set(issues)]; }
function triggerText(rule) { const model = selectedModel(), timer = sources().countdowns.find(item => item.id === rule.cloudCountdownId), consumable = selectedConsumable(); if (rule.triggerType === "device") return model.kind === "event" ? `物模型事件：${model.name} = true` : `物模型：${model.name} ${rule.operator} ${["包含", "不包含"].includes(rule.operator) ? rule.conditionValues.join("、") : rule.conditionValue}${model.unit ? ` ${model.unit}` : ""}`; if (rule.triggerType === "cloud") return `云端：${timer?.name || "-"} <= ${rule.cloudThreshold} ${timer?.unit || ""}`; return `耗材：${consumable?.name || "-"}${rule.consumableEvent === "low" ? "不足" : "耗尽"}`; }
function save(status) { const issues = validate(); if (status === "启用" && issues.length) return showToast(issues[0], "error"); const rule = appState.rule; const output = { ...rule, id: rule.id || `${isSummary() ? "S" : "R"}-${2050 + rules.length}`, productId: appState.selectedProductId, status, updated: "2026-08-25 10:20", revision: (rule.revision || 0) + (appState.editingRule ? 1 : 0), trigger: isSummary() ? `${rule.items.length} 个关联项 · 每日 ${rule.sendTime}` : triggerText(rule), strategy: isSummary() ? `每日一次 · 消息中心${rule.systemNotificationEnabled ? " + 系统通知" : ""}` : `${rule.reminderMode === "each" ? "逐条发送" : `仅发送首条 · ${rule.minIntervalMinutes} 分钟`} · 消息中心${rule.systemNotificationEnabled ? " + 系统通知" : ""}` }; const index = rules.findIndex(item => item.id === rule.id); if (index >= 0) rules[index] = output; else rules.unshift(output); closeRuleDrawer(); window.dispatchEvent(new CustomEvent("message-push:rule-changed")); showToast(status === "启用" ? "规则已发布" : "草稿已保存"); }
function shell() { const title = isSummary() ? "汇总推送" : "普通推送"; const content = appState.ruleStep === 1 ? messageStep() : appState.ruleStep === 2 ? (isSummary() ? summaryRangeStep() : normalTriggerStep()) : deliveryStep(); return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close></div><aside class="drawer rule-drawer"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule ? "编辑" : "新建"}${title}</h2><p>${appState.editingRule ? "规则类型不能直接切换，避免隐式丢失配置。" : title === "汇总推送" ? "一条规则直接管理共享文案和关联项。" : "一个触发条件独立生成一条消息。"}</p></div><button class="icon-btn" data-close>×</button></header>${stepNav()}<div class="drawer-main"><div class="drawer-body"><section class="drawer-content">${content}</section></div></div><footer class="drawer-footer"><span class="save-hint">${appState.ruleStep < 3 ? "完成当前步骤后可继续" : "发布前会检查 English 和必要配置"}</span><div class="footer-actions">${appState.ruleStep > 1 ? `<button class="el-btn" data-prev>上一步</button>` : ""}${appState.ruleStep < 3 ? `<button class="el-btn el-btn--primary" data-next>下一步</button>` : `<><button class="el-btn" data-save-draft>保存草稿</button><button class="el-btn el-btn--primary" data-publish>发布</button></>`}</div></footer></aside></div>`; }
function rerender() { const host = $("#ruleDrawer"); if (!host) return; host.outerHTML = shell(); wire(); renderAnnotations(`rule${appState.ruleStep}${isSummary() ? "summary" : ""}`, `${isSummary() ? "汇总推送" : "普通推送"} · 步骤 ${appState.ruleStep}/3`); }
function insertToken(input, token) { if (!input) return; const start = input.selectionStart ?? input.value.length; input.value = `${input.value.slice(0, start)}${token}${input.value.slice(input.selectionEnd ?? start)}`; appState.rule[input.dataset.content] = input.value; input.focus(); input.setSelectionRange(start + token.length, start + token.length); }
function wire() { const host = $("#ruleDrawer"); host.querySelectorAll("[data-close]").forEach(button => button.onclick = closeRuleDrawer); host.querySelectorAll("[data-step]").forEach(button => button.onclick = () => { appState.ruleStep = +button.dataset.step; rerender(); }); host.querySelectorAll("[data-rule-input]").forEach(input => input.onchange = () => { appState.rule[input.dataset.ruleInput] = input.value; if (["operator", "cloudCountdownId", "triggerType"].includes(input.dataset.ruleInput)) rerender(); }); host.querySelectorAll("[data-content]").forEach(input => { input.onfocus = () => appState.activeContentField = input.dataset.content; input.oninput = () => appState.rule[input.dataset.content] = input.value; }); host.querySelectorAll("[data-placeholder]").forEach(button => button.onclick = () => insertToken(host.querySelector(`[data-content="${appState.activeContentField}"]`), button.dataset.placeholder)); host.querySelectorAll('input[name="trigger"]').forEach(input => input.onchange = () => { appState.rule.triggerType = input.value; rerender(); }); host.querySelectorAll('input[name="time-mode"]').forEach(input => input.onchange = () => { appState.rule.timeMode = input.value; rerender(); }); host.querySelector("[data-open-picker]")?.addEventListener("click", openPicker); host.querySelectorAll("[data-enum-value]").forEach(input => input.onchange = () => { const values = new Set(appState.rule.conditionValues || []); input.checked ? values.add(input.dataset.enumValue) : values.delete(input.dataset.enumValue); appState.rule.conditionValues = [...values]; }); host.querySelectorAll('input[name="mode"]').forEach(input => input.onchange = () => { appState.rule.reminderMode = input.value; rerender(); }); host.querySelector('input[name="system-notification"]')?.addEventListener("change", event => { appState.rule.systemNotificationEnabled = event.target.checked; rerender(); }); host.querySelector("[data-add-item]")?.addEventListener("click", () => itemDialog()); host.querySelectorAll("[data-edit-item]").forEach(button => button.onclick = () => itemDialog(appState.rule.items.find(item => item.itemId === button.dataset.editItem))); host.querySelectorAll("[data-delete-item]").forEach(button => button.onclick = () => { const item = appState.rule.items.find(entry => entry.itemId === button.dataset.deleteItem); if (item) openConfirmationDialog({ title: "删除关联项", description: `删除“${itemName(item)}”后不能恢复。`, confirmLabel: "删除", tone: "danger", onConfirm: () => { appState.rule.items = appState.rule.items.filter(entry => entry.itemId !== item.itemId); appState.rule.items.forEach((entry, index) => entry.displayOrder = index + 1); rerender(); } }); }); host.querySelectorAll("[data-move-item]").forEach(button => button.onclick = () => { const ordered = [...appState.rule.items].sort((a,b) => a.displayOrder-b.displayOrder), index = ordered.findIndex(item => item.itemId === button.dataset.moveItem), target = index + Number(button.dataset.direction); if (target < 0 || target >= ordered.length) return; [ordered[index], ordered[target]] = [ordered[target], ordered[index]]; ordered.forEach((item, itemIndex) => item.displayOrder = itemIndex + 1); appState.rule.items = ordered; rerender(); }); host.querySelector("[data-prev]")?.addEventListener("click", () => { appState.ruleStep--; rerender(); }); host.querySelector("[data-next]")?.addEventListener("click", () => { appState.ruleStep++; rerender(); }); host.querySelector("[data-save-draft]")?.addEventListener("click", () => save("草稿")); host.querySelector("[data-publish]")?.addEventListener("click", () => save("启用")); }
export function openRuleDrawer({ edit = false } = {}) { appState.editingRule = edit; appState.ruleStep = 1; $("#overlayRoot").innerHTML = shell(); wire(); renderAnnotations(`rule1${isSummary() ? "summary" : ""}`, `${isSummary() ? "汇总推送" : "普通推送"} · 步骤 1/3`); }
export function closeRuleDrawer() { closePicker(); $("#ruleDrawer")?.remove(); renderAnnotations("rules", "推送规则列表"); }
export function resetRuleDraft(ruleType = "NORMAL") { appState.rule = { ...newRule(ruleType), productId: appState.selectedProductId }; appState.activeContentField = "title"; }
